  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."users"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_user_col_audit_ins" AFTER INSERT ON "app"."users" REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__col_audit_ins"()';
